def image(name,alt,cls='',eager=False):
 return f'<img class="{cls}" src="assets/{name}.webp" alt="{alt}" width="1600" height="1067" '+('fetchpriority="high" loading="eager"' if eager else 'loading="lazy"')+' decoding="async">'
