 interior=f'<section class="split reverse" id="interior"><div class="split-copy"><div class="eyebrow">02 / KHÔNG GIAN NỘI THẤT</div><h2>Mở cửa.<br>Khép lại ồn ào.</h2><p>Sự tĩnh tại được tạo nên từ những điều có thể chạm tới: chất liệu tinh tế, ánh sáng dịu và cách bố trí hướng đến người sử dụng.</p><p class="small">Ảnh nội thất Lexus minh họa ngôn ngữ thiết kế; trang bị tùy dòng xe và thị trường.</p></div><div class="split-media">{image("interior","Không gian nội thất Lexus")}</div></section>'
 performance=f'<section class="story">{image("story","Lexus trên hành trình")}<div class="story-content"><div class="eyebrow">03 / CẢM GIÁC LÁI</div><h2>Êm ái để tận hưởng.<br>Hứng khởi để khám phá.</h2><p>Mỗi hành trình là một cuộc đối thoại giữa bạn, chiếc xe và con đường phía trước.</p>{link("Trực tiếp cảm nhận","lai-thu.html")}</div></section>'
 tech='<section class="container section"><div class="section-heading"><div><div class="eyebrow">04 / CÔNG NGHỆ & AN TÂM</div><h2>Thông minh một cách tự nhiên.</h2></div><p>Những tiện ích đặt trải nghiệm của người lái ở trung tâm. Trang bị cụ thể cần xác nhận theo phiên bản.</p></div><div class="accordion">'+''.join(f'<details {"open" if i==0 else ""}><summary>{title}</summary><p>{text}</p></details>' for i,(title,text) in enumerate([('Khoang lái hướng đến người lái','Các thao tác được bố trí trong tầm tay, giúp bạn tập trung hơn vào hành trình và tận hưởng không gian xung quanh.'),('Kết nối và giải trí','Không gian giải trí được cân nhắc cùng sự tiện lợi trong sử dụng hàng ngày. Vui lòng xác nhận khả năng tương thích và trang bị với chuyên viên.'),('Hỗ trợ lái & an toàn','Các hệ thống hỗ trợ không thay thế sự tập trung của người lái. Phạm vi hoạt động và trang bị khác nhau theo phiên bản.'),('Chất liệu & nghệ thuật Takumi','Cảm hứng thủ công thể hiện trong sự hòa hợp của chất liệu, bề mặt và chi tiết hoàn thiện. Khám phá chất liệu trực tiếp khi đến showroom.')]))+'</div></section>'
 gallery_items=[mid,'interior','detail','story','rx','lx','es','showroom']
