 variants=f'<section class="section stone" id="versions"><div class="container"><div class="section-heading"><div><div class="eyebrow">06 / LỰA CHỌN PHIÊN BẢN</div><h2>Phù hợp với điều bạn tìm kiếm.</h2></div><p class="small">Cấu hình & giá demo để duyệt template. Không phải cam kết bán hàng.</p></div><div class="variant-grid">'+''.join(f'<article class="variant"><div class="eyebrow">{label}</div><h3>Lexus {name} {v}</h3><p class="price">{price} ₫</p><ul><li>{power}</li><li>Không gian tinh tế</li><li>Tư vấn cấu hình riêng</li></ul>{btn("Khám phá phiên bản","phien-ban.html")}</article>' for label,v,price,power in [('THANH LỊCH','350h',m['price'],'Hybrid · cấu hình minh họa'),('TINH TẾ','Luxury','4.330.000.000','Trang bị nâng cao · minh họa'),('CÁ TÍNH','F SPORT','4.940.000.000','Phong cách thể thao · minh họa')])+'</div></div></section>' if isrx else f'<section class="container section" id="versions"><div class="eyebrow">LỰA CHỌN PHIÊN BẢN</div><h2>Lexus {name}, theo phong cách của bạn.</h2><p style="margin-top:22px">Giá minh họa từ {m["price"]} ₫. Hãy trao đổi với chuyên viên để chọn phiên bản phù hợp.</p><div class="actions">{btn("Nhận tư vấn phiên bản","bao-gia.html")}</div></section>'
 specs='<section class="container section"><div class="section-heading"><div><div class="eyebrow">07 / THÔNG TIN SỞ HỮU</div><h2>Tìm hiểu kỹ hơn.</h2></div></div><div class="accordion"><details><summary>Kích thước & không gian</summary><p>Template dành cho thông số chiều dài, chiều rộng, chiều cao, chiều dài cơ sở và dung tích khoang hành lý. Dữ liệu kỹ thuật chính thức sẽ được cập nhật theo phiên bản và thị trường.</p></details><details><summary>Động cơ & vận hành</summary><p>Vui lòng trao đổi với chuyên viên để xác nhận động cơ, công suất và hệ dẫn động của chiếc xe bạn quan tâm.</p></details><details><summary>Bảo hành & chăm sóc</summary><p>Chính sách bảo hành, điều kiện bảo dưỡng và hỗ trợ cần được xác nhận trong báo giá chính thức. <a href="dich-vu.html"><u>Xem trải nghiệm chăm sóc</u></a>.</p></details></div><div class="notice">Cần một kế hoạch sở hữu phù hợp? <a href="tai-chinh.html"><u>Khám phá phương án tài chính minh họa ↗</u></a></div></section>'
 lead=f'<section class="section stone"><div class="container lead-layout"><div class="lead-copy"><div class="eyebrow">MỘT BƯỚC ĐẾN GẦN HƠN</div><h2>Lexus {name}.<br>Dành riêng cho bạn.</h2><p>Chọn dòng xe bạn quan tâm và để lại mong muốn. Một cuộc trò chuyện là khởi đầu cho hành trình mới.</p><div class="actions">{link("Đăng ký lái thử","lai-thu.html")}</div></div>{form()}</div></section>'
 related=f'<section class="container section"><div class="section-heading"><h2>Tiếp tục khám phá.</h2>{link("Tất cả dòng xe","models.html")}</div><div class="model-grid">'+''.join(card(x) for x in models if x['id']!=mid)[:0]+'</div></section>'
 related=f'<section class="container section"><div class="section-heading"><h2>Tiếp tục khám phá.</h2>{link("Tất cả dòng xe","models.html")}</div><div class="model-grid">'+''.join(card(x) for x in [x for x in models if x['id']!=mid][:3])+'</div></section>'
