page('so-sanh.html','So sánh dòng xe',intro('Đặt những lựa chọn cạnh nhau.','Một góc nhìn rõ ràng hơn trước khi chọn chiếc Lexus của bạn. Bộ so sánh mẫu gồm RX, ES và LX.','SO SÁNH LEXUS')+'<section class="container section comparison"><div class="compare-grid">'+''.join(f'<article>{image(m["id"],"Lexus "+m["name"])}<h3>Lexus {m["name"]}</h3><p>{m["price"]} ₫ · Demo</p>{link("Khám phá",m["id"]+".html")}</article>' for m in models[:3])+'</div><label class="compare-toggle"><input id="different" type="checkbox"> Chỉ hiện điểm khác nhau</label><div class="table-wrap"><table class="data-table"><thead><tr><th>Tiêu chí</th><th>Lexus RX</th><th>Lexus ES</th><th>Lexus LX</th></tr></thead><tbody><tr><td>Kiểu dáng</td><td>SUV</td><td>Sedan</td><td>SUV</td></tr><tr><td>Hệ truyền động mẫu</td><td>Hybrid</td><td>Hybrid</td><td>Xăng</td></tr><tr><td>Số chỗ mẫu</td><td>5</td><td>5</td><td>7</td></tr><tr><td>Phong cách</td><td>Linh hoạt, tinh tế</td><td>Thanh lịch, thư thái</td><td>Rộng rãi, mạnh mẽ</td></tr><tr class="same"><td>Tư vấn cá nhân</td><td>Có</td><td>Có</td><td>Có</td></tr><tr class="same"><td>Đăng ký lái thử</td><td>Có</td><td>Có</td><td>Có</td></tr></tbody></table></div><p class="notice">Bảng cấu hình cố định để duyệt template. Trên điện thoại có thể cuộn ngang bảng. Thông số và giá cần xác nhận theo phiên bản thực tế.</p></section>'+conversion())
