page('uu-dai.html','Đặc quyền sở hữu',intro('Để trải nghiệm thêm trọn vẹn.','Những lời mời dành cho hành trình Lexus của bạn. Nội dung chương trình dưới đây là mẫu thiết kế.','ĐẶC QUYỀN SỞ HỮU')+f'<section class="container section"><div class="editorial-grid"><article class="editorial-card">{image("rx","Lexus RX")}<div class="eyebrow">CHƯƠNG TRÌNH MẪU · THÁNG 09/2026</div><h3>Buổi hẹn khám phá Lexus RX.</h3><p>Trải nghiệm không gian, thiết kế và cảm giác lái theo lịch hẹn cá nhân.</p>{link("Chi tiết chương trình","chi-tiet-uu-dai.html")}</article><article class="editorial-card">{image("interior","Nội thất Lexus")}<div class="eyebrow">DỊCH VỤ CÁ NHÂN</div><h3>Tư vấn lựa chọn dành riêng.</h3><p>Dành thời gian tìm hiểu màu sắc, chất liệu và phương án sở hữu.</p>{link("Đặt lịch tư vấn","lien-he.html")}</article></div><p class="notice">Các chương trình minh họa không tạo quyền lợi hoặc ưu đãi thực tế. Vui lòng thay bằng nội dung đã được phê duyệt trước khi công bố.</p></section>'+conversion())
page('chi-tiet-uu-dai.html','Buổi hẹn cùng Lexus RX',intro('Một buổi hẹn. Nhiều cảm hứng.','Khám phá Lexus RX trong không gian và thời gian dành riêng cho bạn.','CHƯƠNG TRÌNH MẪU')+image('rx','Lexus RX')+'<article class="article"><div class="eyebrow">MẪU NỘI DUNG CHƯƠNG TRÌNH</div><h2>Trải nghiệm theo nhịp riêng.</h2><p>Buổi hẹn mẫu gồm giới thiệu thiết kế, khám phá khoang nội thất và trao đổi về nhu cầu sử dụng. Lịch lái thử cần được showroom xác nhận.</p><h2>Thông tin minh họa</h2><p>Thời gian mẫu: 01–30.09.2026. Dòng xe: Lexus RX. Địa điểm: showroom Lexus Thăng Long, Cầu Giấy, Hà Nội.</p><p>Đây không phải chương trình đang mở đăng ký thực tế và không kèm cam kết ưu đãi.</p>'+btn('Xem form đăng ký mẫu','lai-thu.html')+'</article>')
page('phien-ban.html','Lexus RX 350h',f'<section class="hero model-hero">{image("rx","Lexus RX 350h","hero-media",True)}<div class="container"><div class="eyebrow">THE LEXUS RX · PHIÊN BẢN MẪU</div><h1>RX 350h</h1><p>Hybrid. Tinh tế và đầy cảm hứng.</p><div class="actions">{btn("Nhận báo giá","bao-gia.html","light")}{link("Xem dòng RX","rx.html")}</div></div></section><section class="container section"><div class="section-heading"><div><div class="eyebrow">MỘT LỰA CHỌN CÂN BẰNG</div><h2>Đồng điệu với mỗi ngày.</h2></div><p>Trang mẫu cho phiên bản RX 350h. Giá, trang bị và cấu hình cần được cập nhật theo dữ liệu chính thức.</p></div><div class="spec-strip"><div><small>PHIÊN BẢN</small><strong>350h</strong></div><div><small>ĐỘNG LỰC</small><strong>Hybrid</strong></div><div><small>KHÔNG GIAN MẪU</small><strong>5 chỗ</strong></div><div><small>GIÁ DEMO</small><strong>3,43 tỷ ₫</strong></div></div></section><section class="split stone"><div class="split-media">{image("interior","Nội thất Lexus minh họa")}</div><div class="split-copy"><div class="eyebrow">DÀNH CHO BẠN</div><h2>Khám phá trực tiếp.<br>Lựa chọn tự tin.</h2><p>Trải nghiệm chất liệu, tư thế ngồi và không gian thực tế tại buổi hẹn cá nhân.</p>{link("Đặt lịch lái thử","lai-thu.html")}</div></section>'+conversion(),True,True)
# EDITORIAL / BRAND
page('experience.html','Thế giới Lexus',f'<section class="hero compact-hero">{image("detail","Nghệ thuật hoàn thiện Lexus","hero-media",True)}<div class="container"><div class="eyebrow">THE LEXUS WAY</div><h1>Vẻ đẹp của<br>sự tận tâm.</h1></div></section><section class="container section"><div class="section-heading"><div><div class="eyebrow">TRIẾT LÝ LEXUS</div><h2>Chạm đến cảm xúc.<br>Từ những điều giản dị.</h2></div><p>Một góc nhìn về sự sang trọng: chất liệu được chăm chút, chuyển động hài hòa và cảm giác được đón tiếp.</p></div></section><section class="split stone" id="takumi"><div class="split-media">{image("detail","Chi tiết chế tác Lexus")}</div><div class="split-copy"><div class="eyebrow">01 / TAKUMI</div><h2>Đôi tay.<br>Đôi mắt. Trái tim.</h2><p>Vẻ đẹp của chế tác nằm trong cách từng chi tiết được quan sát và hoàn thiện. Đó là sự kiên nhẫn dành cho những điều nhỏ nhất.</p>{link("Câu chuyện chế tác","bai-viet.html")}</div></section><section class="split reverse" id="omotenashi"><div class="split-copy"><div class="eyebrow">02 / OMOTENASHI</div><h2>Mỗi vị khách.<br>Một sự thấu hiểu.</h2><p>Tinh thần hiếu khách bắt đầu bằng việc lắng nghe. Từ một cuộc hẹn riêng đến không gian êm dịu, mọi trải nghiệm đều hướng đến sự thoải mái của bạn.</p>{link("Ghé thăm showroom","showroom.html")}</div><div class="split-media">{image("interior","Không gian nội thất Lexus")}</div></section><section class="story">{image("story","Hành trình Lexus")}<div class="story-content"><div class="eyebrow">03 / LEXUS ELECTRIFIED</div><h2>Năng lượng mới.<br>Cảm hứng vẹn nguyên.</h2><p>Một cách cảm nhận mới về chuyển động. Khám phá các dòng xe Hybrid và tìm lựa chọn cho hành trình của mình.</p>{link("Khám phá dòng xe","models.html")}</div></section>'+conversion(),True)
page('tin-tuc.html','Góc nhìn Lexus',intro('Những câu chuyện đáng dành thời gian.','Thiết kế, con người và những trải nghiệm làm nên một góc nhìn Lexus.','LEXUS JOURNAL')+f'<section class="container section"><div class="editorial-grid" style="align-items:center"><a href="bai-viet.html">{image("detail","Nghệ thuật hoàn thiện Lexus")}</a><div><div class="eyebrow">CÂU CHUYỆN NỔI BẬT</div><h2>Sự hoàn hảo bắt đầu<br>từ những điều nhỏ nhất.</h2><p style="margin-top:22px">Một góc nhìn về chất liệu, đường nét và sự chăm chút trong thiết kế.</p>{link("Đọc câu chuyện","bai-viet.html")}</div></div></section><section class="container section" style="padding-top:0">{news()}</section>'+conversion())
page('bai-viet.html','Sự tinh tế trong từng chi tiết',intro('Sự tinh tế trong từng chi tiết.','Một góc nhìn về nghệ thuật chế tác, nơi cảm xúc bắt đầu từ những điều có thể chạm tới.','LEXUS JOURNAL · BÀI VIẾT DEMO · 21.09.2026')+image('detail','Chi tiết vật liệu Lexus')+f'<article class="article"><p>Một chiếc xe được cảm nhận theo nhiều cách. Từ ánh nhìn đầu tiên đến lúc đặt tay lên vô-lăng, những ấn tượng nhỏ dần kết nối thành một trải nghiệm trọn vẹn.</p><h2>Vật liệu kể câu chuyện riêng.</h2><p>Ánh sáng lướt qua bề mặt, một đường chỉ khâu gọn gàng hay cảm giác khi chạm vào chất liệu đều góp phần tạo nên không gian. Sự sang trọng có thể hiện diện trong chính những điều giản dị ấy.</p><figure>{image("interior","Không gian Lexus")}<figcaption>Nội thất Lexus minh họa. Cấu hình khác nhau theo mẫu xe và thị trường.</figcaption></figure><h2>Khoảng lặng trên mỗi hành trình.</h2><p>Trong một ngày nhiều chuyển động, khoang xe có thể trở thành nơi để tìm lại nhịp riêng. Cách bố trí, ánh sáng và sự thuận tiện cùng tạo nên cảm giác dễ chịu.</p><blockquote>Đôi khi, điều đáng nhớ nhất là cảm giác mọi thứ đã được nghĩ đến.</blockquote><h2>Cảm nhận bằng chính bạn.</h2><p>Hình ảnh chỉ kể một phần câu chuyện. Một cuộc hẹn tại showroom là cơ hội để bạn tự cảm nhận chất liệu, không gian và lựa chọn phù hợp.</p>{link("Khám phá Lexus RX","rx.html")}</article>'+conversion())
page('showroom.html','Showroom & tư vấn',f'<section class="hero compact-hero">{image("showroom","Không gian showroom Lexus","hero-media",True)}<div class="container"><div class="eyebrow">WELCOME TO YOUR LEXUS EXPERIENCE</div><h1>Một không gian.<br>Dành để đón bạn.</h1></div></section><section class="container section"><div class="contact-section"><div><div class="eyebrow">LEXUS THĂNG LONG · CẦU GIẤY, HÀ NỘI</div><h2>Hân hạnh được<br>đồng hành cùng bạn.</h2>{contact()}<div class="actions">{btn("Đặt lịch hẹn","lien-he.html")}{link("Tư vấn trực tiếp","bao-gia.html")}</div></div>{image("interior","Không gian trải nghiệm Lexus")}</div></section><section class="section stone"><div class="container"><div class="section-heading"><h2>Mỗi cuộc hẹn đều có ý nghĩa.</h2></div><div class="shortcut-grid"><div class="shortcut"><span class="number">01</span><h3>Khám phá xe</h3><p>Tìm hiểu thiết kế & không gian</p></div><div class="shortcut"><span class="number">02</span><h3>Lái thử</h3><p>Cảm nhận thực tế theo lịch hẹn</p></div><div class="shortcut"><span class="number">03</span><h3>Tư vấn riêng</h3><p>Lựa chọn cấu hình phù hợp</p></div><div class="shortcut"><span class="number">04</span><h3>Chăm sóc</h3><p>Đồng hành sau mỗi hành trình</p></div></div></div></section>'+conversion(),True)
page('dich-vu.html','Dịch vụ & chăm sóc',intro('An tâm, trên mỗi chặng đường.','Sự quan tâm tiếp nối sau buổi gặp đầu tiên. Khám phá trải nghiệm chăm sóc dành cho chủ xe.','LEXUS OWNERSHIP')+f'<section class="split"><div class="split-media">{image("detail","Chăm chút từng chi tiết Lexus")}</div><div class="split-copy"><div class="eyebrow">CHĂM SÓC TẬN TÂM</div><h2>Luôn có người<br>lắng nghe bạn.</h2><p>Đặt lịch trao đổi về bảo dưỡng, kiểm tra xe và nhu cầu chăm sóc. Các dịch vụ và chính sách sẽ được đơn vị triển khai xác nhận.</p>{link("Đặt lịch tư vấn dịch vụ","lien-he.html")}</div></section><section class="container section"><div class="accordion"><details open><summary>Bảo dưỡng theo lịch hẹn</summary><p>Chuyên viên tư vấn sẽ hướng dẫn kế hoạch bảo dưỡng phù hợp với xe và lịch trình sử dụng của bạn.</p></details><details><summary>Chính sách bảo hành</summary><p>Phạm vi và điều kiện bảo hành cần căn cứ vào hồ sơ xe, phiên bản và chính sách chính thức tại thời điểm mua.</p></details><details><summary>Hỗ trợ chủ xe</summary><p>Liên hệ đơn vị bán xe để được hướng dẫn kênh hỗ trợ thực tế. Hotline trên template hiện là số demo.</p></details></div></section>'+conversion())
faqs=[('Tôi có thể đặt lịch lái thử như thế nào?','Chọn trang Đăng ký lái thử, điền thông tin mẫu và xem giao diện xác nhận. Template này chưa kết nối hệ thống tiếp nhận lịch hẹn.'),('Giá hiển thị có phải giá bán hiện hành không?','Không. Giá và cấu hình được sử dụng để minh họa thiết kế. Giá bán thực tế phải được xác nhận bằng báo giá chính thức.'),('Các hình ảnh có đúng phiên bản Việt Nam không?','Ảnh minh họa được lấy từ nguồn Lexus ở nhiều thị trường. Màu sắc và trang bị có thể khác xe phân phối tại Việt Nam.'),('Thông tin của tôi có được gửi đi không?','Template HTML/CSS chưa có máy chủ xử lý form. Không nhập thông tin thật. Biểu mẫu chỉ chuyển sang một trang xác nhận mẫu.'),('Có thể tư vấn qua Zalo không?','Khu vực liên hệ đã có vị trí dành cho Zalo; số demo chưa kết nối tài khoản. Khi triển khai sẽ thay bằng đường dẫn chính thức.')]
page('faq.html','Câu hỏi thường gặp',intro('Những điều bạn muốn biết.','','HỖ TRỢ')+'<section class="container section"><div class="accordion">'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in faqs)+'</div></section>'+conversion())
page('privacy.html','Quyền riêng tư',intro('Thông tin về quyền riêng tư.','','TEMPLATE DEMO')+'<article class="article"><h2>Phạm vi bản demo</h2><p>Website này là mẫu HTML/CSS cục bộ. Không có hệ thống tài khoản, công cụ phân tích hoặc dịch vụ tiếp nhận thông tin được tích hợp.</p><h2>Biểu mẫu minh họa</h2><p>Chỉ sử dụng thông tin giả để kiểm tra bố cục và trạng thái. Khi bấm nút, trình duyệt chuyển sang trang demo; dữ liệu không được gửi cho tư vấn viên. Các trường có thể xuất hiện trong URL và lịch sử trình duyệt.</p><h2>Khi đưa vào sử dụng</h2><p>Đơn vị vận hành cần thay nội dung này bằng chính sách thực tế, xác định chủ thể xử lý, mục đích thu thập, thời hạn lưu giữ và cách người dùng thực hiện quyền đối với dữ liệu.</p></article>')
page('terms.html','Điều khoản sử dụng',intro('Điều khoản bản thiết kế.','','TEMPLATE DEMO')+'<article class="article"><h2>Website minh họa</h2><p>Đây là bản thiết kế độc lập để đánh giá giao diện, không đại diện cho Lexus hoặc một đại lý được ủy quyền.</p><h2>Nội dung tham khảo</h2><p>Giá, liên hệ, chương trình và phương án tài chính đều là dữ liệu demo. Không có giao dịch hoặc dịch vụ thực tế được xác lập qua bản thiết kế này.</p><h2>Hình ảnh và thương hiệu</h2><p>Lexus và các hình ảnh xe thuộc chủ sở hữu tương ứng. Cần xác nhận quyền sử dụng hình ảnh, thương hiệu và thông tin thương mại trước khi công bố website.</p></article>')
